const state={csrf:"",bootstrap:null,dashboard:null,projects:[],groups:[],repos:[],workflowAlerts:[],services:[],dependencies:[],runbooks:[],alerts:[],maintenance:[],monitorEvents:[],conversations:[],jobs:[],deliveries:[],environments:[],deployments:[],incidents:[],approvals:[],audit:[],contacts:[],githubDiscovery:null,runtimeReady:false,runtimeComponents:[],whatsapp:null,githubSettings:null,aiSettings:null,ownerSettings:null,briefingSettings:null,view:"overview",incidentFilter:"",pairingTimer:null,setupProjectId:"",setupStep:0,openServiceId:""};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const titles={setup:["GET STARTED","Guided setup"],overview:["OPERATIONS","Overview"],monitoring:["OPERATIONS","Monitoring"],assistant:["OPERATIONS","Assistant"],incidents:["INCIDENT RESPONSE","Incidents"],approvals:["CONTROL GATE","Approvals"],deployments:["DELIVERY","Deployments"],projects:["CONFIGURATION","Projects"],channels:["CONNECTIONS","WhatsApp"],repositories:["SOURCE ACCESS","Repositories"],environments:["DELIVERY POLICY","Environments"],audit:["ASSURANCE","Audit trail"],system:["PLATFORM","System health"]};

async function api(path,options={}){const headers={"Content-Type":"application/json",...(options.headers||{})};if(state.csrf)headers["X-Echo-CSRF"]=state.csrf;const response=await fetch(path,{credentials:"same-origin",...options,headers});if(response.status===401)throw new Error("AUTH_REQUIRED");if(response.status===204)return null;const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.error?.message||`Request failed (${response.status})`);return data}
function escapeHTML(v=""){return String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function when(v){if(!v||String(v).startsWith("0001-01-01"))return"—";const d=new Date(v);if(Number.isNaN(d.getTime()))return"—";return new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(d)}
function normalizedRuntime(runtime){const components=[...(runtime?.components||[])];for(const [name,status] of Object.entries(runtime?.checks||{})){if(!components.some(component=>component.name===name))components.push({name,status,detail:"waiting for first report"})}return components.sort((a,b)=>a.name.localeCompare(b.name))}
function durationSeconds(v){const seconds=Number(v)||0;if(!seconds)return"disabled";if(seconds%3600===0)return`${seconds/3600}h`;if(seconds%60===0)return`${seconds/60}m`;return`${seconds}s`}
function elapsedSeconds(v){const seconds=Math.max(0,Math.floor(Number(v)||0));if(seconds<60)return`${seconds}s`;if(seconds<3600)return`${Math.floor(seconds/60)}m ${seconds%60}s`;return`${Math.floor(seconds/3600)}h ${Math.floor((seconds%3600)/60)}m`}
function badge(v){return `<span class="badge ${escapeHTML(v)}">${escapeHTML(String(v).replaceAll("_"," "))}</span>`}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2800)}
function empty(title,body){return `<div class="empty"><b>${escapeHTML(title)}</b>${escapeHTML(body)}</div>`}

async function boot(){try{state.bootstrap=await api("/api/v1/bootstrap");state.csrf=state.bootstrap.csrf||cookie("echo_csrf");$("#login").hidden=true;$("#shell").hidden=false;$("#environment").textContent=state.bootstrap.environment;await refreshAll();const requested=location.hash.slice(1);const destination=requested&&requested!=="overview"?requested:(setupStatus().complete?"overview":"setup");if(destination==="setup")state.setupStep=recommendedSetupStep();navigate(destination)}catch(err){if(err.message==="AUTH_REQUIRED"){showLogin()}else{$("#login-error").textContent=err.message}}}
function showLogin(){$("#login").hidden=false;$("#shell").hidden=true}
function cookie(name){return document.cookie.split("; ").find(v=>v.startsWith(name+"="))?.split("=").slice(1).join("=")||""}

async function refreshAll(){const requests=[api("/api/v1/dashboard"),api("/api/v1/projects"),api("/api/v1/groups"),api("/api/v1/repositories"),api("/api/v1/github/workflow-alerts?status=open"),api("/api/v1/services"),api("/api/v1/service-dependencies"),api("/api/v1/service-runbooks"),api("/api/v1/monitor/alerts?status=open"),api("/api/v1/maintenance"),api("/api/v1/monitor/events?limit=20&includeDetails=false"),api("/api/v1/assistant/conversations"),api("/api/v1/jobs"),api("/api/v1/whatsapp/outbox"),api("/api/v1/environments"),api("/api/v1/deployments"),api("/api/v1/incidents"),api("/api/v1/approvals"),api("/api/v1/audit"),api("/api/v1/whatsapp"),api("/api/v1/settings/github"),api("/api/v1/settings/ai"),api("/api/v1/whatsapp/contacts"),api("/api/v1/settings/owner"),api("/api/v1/settings/briefing"),api("/api/v1/runtime")];const [dashboard,projects,groups,repos,workflowAlerts,services,dependencies,runbooks,alerts,maintenance,monitorEvents,conversations,jobs,deliveries,environments,deployments,incidents,approvals,audit,whatsapp,githubSettings,aiSettings,contacts,ownerSettings,briefingSettings,runtime]=await Promise.all(requests);Object.assign(state,{dashboard,projects:projects||[],groups:groups||[],repos:repos||[],workflowAlerts:workflowAlerts||[],services:services||[],dependencies:dependencies||[],runbooks:runbooks||[],alerts:alerts||[],maintenance:maintenance||[],monitorEvents:monitorEvents||[],conversations:conversations||[],jobs:jobs||[],deliveries:deliveries||[],environments:environments||[],deployments:deployments||[],incidents:incidents||[],approvals:approvals||[],audit:audit||[],whatsapp,githubSettings,aiSettings,contacts:contacts||[],ownerSettings,briefingSettings,runtimeReady:Boolean(runtime?.ready),runtimeComponents:normalizedRuntime(runtime)});state.bootstrap.features.github=Boolean(githubSettings?.configured);state.bootstrap.features.ai=Boolean(aiSettings?.configured);state.bootstrap.features.owner=Boolean(ownerSettings?.configured);$("#incident-count").textContent=dashboard.openIncidents;$("#approval-count").textContent=dashboard.pendingApprovals;const alertCount=$("#alert-count");if(alertCount)alertCount.textContent=state.alerts.length+state.workflowAlerts.length;updateWhatsAppSummary();updateSetupProgress();monitorPairing()}
function updateWhatsAppSummary(){const connected=state.whatsapp?.status==="connected";$("#wa-dot").classList.toggle("online",connected);$("#wa-status").textContent=state.whatsapp?.status||"unknown"}
function monitorPairing(){clearTimeout(state.pairingTimer);if(!["pairing_requested","pairing","connecting"].includes(state.whatsapp?.status))return;state.pairingTimer=setTimeout(async()=>{try{state.whatsapp=await api("/api/v1/whatsapp");updateWhatsAppSummary();updateSetupProgress();if(["channels","setup"].includes(state.view))render();monitorPairing()}catch(err){if(err.message!=="AUTH_REQUIRED")toast(err.message)}},1000)}

function navigate(view){if(!titles[view])view="overview";state.view=view;location.hash=view;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$("#view-kicker").textContent=titles[view][0];$("#view-title").textContent=titles[view][1];$(".sidebar").classList.remove("open");render()}
function render(){const fn={setup:renderSetup,overview:renderOverview,monitoring:renderMonitoring,assistant:renderAssistant,incidents:renderIncidents,approvals:renderApprovals,deployments:renderDeployments,projects:renderProjects,channels:renderChannels,repositories:renderRepositories,environments:renderEnvironments,audit:renderAudit,system:renderSystem}[state.view];$("#content").innerHTML=fn();if(state.view==="repositories"&&state.workflowAlerts.length)$("#content").insertAdjacentHTML("afterbegin",repositoryWorkflowAlertPanel())}

function selectedSetupProject(){let project=state.projects.find(p=>p.id===state.setupProjectId);if(!project){project=state.projects.find(p=>p.enabled)||state.projects[0];state.setupProjectId=project?.id||""}return project}
function setupStatus(){const project=selectedSetupProject();const repos=project?state.repos.filter(r=>r.projectId===project.id&&r.enabled):[];const groups=project?state.groups.filter(g=>g.projectId===project.id&&g.enabled):[];const whatsapp=state.whatsapp?.status==="connected";const owner=Boolean(state.ownerSettings?.configured);const checks=[whatsapp,Boolean(project),repos.length>0,groups.length>0];return{project,repos,groups,whatsapp,owner,checks,count:checks.filter(Boolean).length,complete:checks.every(Boolean),intakeReady:whatsapp&&Boolean(project)&&groups.length>0,diagnosisReady:whatsapp&&owner&&Boolean(project)&&groups.length>0&&repos.length>0&&Boolean(state.bootstrap?.features?.github)&&Boolean(state.bootstrap?.features?.ai)}}
function recommendedSetupStep(){const s=setupStatus();const missing=s.checks.findIndex(v=>!v);return missing<0?4:missing}
function recommendedIntakeStep(){const s=setupStatus();if(!s.whatsapp)return 0;if(!s.project)return 1;if(!s.groups.length)return 3;return 4}
function updateSetupProgress(){const el=$("#setup-progress");if(el)el.textContent=`${setupStatus().count}/4`}
function setupCheck(done,label,detail){return `<div class="setup-check ${done?"done":"pending"}"><span>${done?"✓":"○"}</span><div><strong>${escapeHTML(label)}</strong><p>${escapeHTML(detail)}</p></div></div>`}
function setupBanner(){const s=setupStatus();if(s.complete)return"";return `<section class="setup-banner"><div><p class="eyebrow">SETUP IN PROGRESS · ${s.count} OF 4 COMPLETE</p><h2>Finish connecting Echo to your team</h2><p>${s.intakeReady?"Message intake is ready. Link a repository to enable code-aware diagnosis.":"The guided setup keeps the WhatsApp account, project, code and group in the right order."}</p></div><button class="button primary" data-resume-setup>Continue setup</button></section>`}

function renderSetup(){const s=setupStatus();const labels=["Connect WhatsApp","Choose project","Link code","Bind group","Test the flow"];const panels=[setupWhatsAppPanel(s),setupProjectPanel(s),setupRepositoryPanel(s),setupGroupPanel(s),setupTestPanel(s)];return `<section class="setup-hero"><div><p class="eyebrow">ONE SAFE PATH FROM REPORT TO FIX</p><h2>Set up Echo for a team</h2><p>A project is the hub that links one team’s WhatsApp groups to the exact repositories Echo may inspect. Echo’s number is connected once, then you add that contact to each group and bind the group here.</p></div><div class="setup-readiness"><span class="${s.intakeReady?"ready":"waiting"}">${s.intakeReady?"✓":"○"} Message intake</span><span class="${s.diagnosisReady?"ready":"waiting"}">${s.diagnosisReady?"✓":"○"} Code diagnosis</span></div></section><div class="setup-layout"><aside class="setup-stepper" aria-label="Setup steps">${labels.map((label,index)=>`<button class="setup-step ${state.setupStep===index?"active":""} ${index<4&&s.checks[index]?"complete":""}" data-setup-step="${index}"><span>${index<4&&s.checks[index]?"✓":index+1}</span><div><strong>${label}</strong><small>${["One dedicated Echo account","The team boundary","Read-only evidence first","Add in WhatsApp, bind here","Send a real @mention"][index]}</small></div></button>`).join("")}</aside><section class="card setup-panel">${panels[state.setupStep]||panels[0]}</section></div>`}
function setupWhatsAppPanel(s){const waiting=["pairing_requested","pairing","connecting"].includes(state.whatsapp?.status);let body;if(s.whatsapp){body=`<div class="setup-success"><span>✓</span><div><strong>Echo is connected</strong><p>${escapeHTML(state.whatsapp.deviceJid||"The dedicated WhatsApp account is online.")}</p></div></div><div class="setup-actions"><button class="button primary" data-setup-step="1">Continue to project</button><button class="button secondary" data-go="channels">Connection details</button></div>`}else if(state.whatsapp?.qrCode){body=`<div class="qr-box" aria-live="polite"><p>On the dedicated Echo phone, open <b>WhatsApp → Linked devices → Link a device</b>.</p><img src="/api/v1/whatsapp/qr.png?v=${encodeURIComponent(state.whatsapp.updatedAt||Date.now())}" alt="Fresh WhatsApp pairing QR code"><p class="muted">This QR rotates automatically and should be treated as a secret.</p></div>`}else{body=`<div class="setup-callout"><strong>${waiting?"Preparing a fresh QR code…":"Connect Echo’s dedicated WhatsApp account"}</strong><p>This is a one-time system connection. A fresh QR is created only after you request it, so the page never relies on a stale code.</p></div>${state.whatsapp?.lastError?`<p class="form-error">${escapeHTML(state.whatsapp.lastError)}</p>`:""}<button class="button primary" id="link-device" ${waiting?"disabled":""}>${waiting?"Preparing…":"Link device"}</button>`}return `<div class="setup-panel-head"><p class="eyebrow">STEP 1</p><h2>Connect Echo to WhatsApp</h2><p>Use a dedicated account that can be added to the team groups you want Echo to monitor.</p></div><div class="setup-panel-body">${body}</div>`}
function setupProjectPanel(s){return `<div class="setup-panel-head"><p class="eyebrow">STEP 2</p><h2>Create or choose a project</h2><p>The project is Echo’s safety boundary. It joins a team’s group conversation to only that team’s repositories and environments.</p></div><div class="setup-panel-body">${state.projects.length?`<label class="setup-project-picker">Project<select id="setup-project-select">${state.projects.map(p=>`<option value="${p.id}" ${p.id===s.project?.id?"selected":""}>${escapeHTML(p.name)}${p.enabled?"":" · disabled"}</option>`).join("")}</select></label><div class="setup-relations">${setupCheck(true,s.project?.name||"Project selected",s.project?.description||"Selected project")}${setupCheck(s.repos.length>0,`${s.repos.length} linked ${s.repos.length===1?"repository":"repositories"}`,s.repos.length?"Available for code evidence":"Add code in the next step")}${setupCheck(s.groups.length>0,`${s.groups.length} bound ${s.groups.length===1?"group":"groups"}`,s.groups.length?"Ready for mention intake":"Bind a group after linking code")}</div>`:empty("No projects yet","Create the team project that will own the repository and group relationships.")}<div class="setup-actions"><button class="button secondary" id="setup-create-project">Create new project</button>${s.project?`<button class="button primary" data-setup-step="2">Use ${escapeHTML(s.project.name)}</button>`:""}</div></div>`}
function setupRepositoryPanel(s){const github=Boolean(state.githubSettings?.configured);const list=s.repos.length?`<div class="setup-list">${s.repos.map(r=>`<div><span class="setup-list-icon">⌘</span><p><strong>${escapeHTML(r.owner)}/${escapeHTML(r.name)}</strong><small>${escapeHTML(r.role)} · ${r.readOnly?"read-only":"write gated"}</small></p>${badge(r.enabled?"enabled":"disabled")}</div>`).join("")}</div>`:empty("No repository linked","Echo can receive a report without code access, but it cannot investigate the codebase.");return `<div class="setup-panel-head"><p class="eyebrow">STEP 3</p><h2>Give Echo scoped code access</h2><p>Connect a fine-grained token limited to the repositories Echo may inspect. Keep repositories read-only until the investigation flow is proven.</p></div><div class="setup-panel-body">${s.project?`<div class="context-pill">Project <strong>${escapeHTML(s.project.name)}</strong></div>${github?`<div class="setup-success compact"><span>✓</span><div><strong>GitHub connected as ${escapeHTML(state.githubSettings.account||"your account")}</strong><p>The encrypted token is available to workers but is never returned to the browser.</p></div></div>${list}`:`<div class="setup-warning"><strong>Connect GitHub before linking code</strong><p>Enter a fine-grained personal access token here in Echo. It will be validated, encrypted and stored in MariaDB; only the encryption key remains in the server environment.</p></div>${list}`}<div class="setup-actions">${github?`<button class="button secondary" id="setup-add-repo">Link repository</button><button class="quiet" id="configure-github-token">Replace token</button>`:`<button class="button secondary" id="configure-github-token">Configure GitHub token</button>`}<button class="button primary" data-setup-step="3">${s.repos.length?"Continue to group":"Continue with intake only"}</button></div>`:`<div class="setup-warning"><strong>Choose a project first</strong><p>Repository access must belong to a project.</p></div><button class="button secondary" data-setup-step="1">Back to project</button>`}</div>`}
function setupGroupPanel(s){const bound=s.groups.length?`<div class="setup-list">${s.groups.map(g=>`<div><span class="setup-list-icon">⌁</span><p><strong>${escapeHTML(g.groupName)}</strong><small>${escapeHTML(g.groupJid)} · ${g.mentionRequired?"mention required":"all messages"}</small></p>${badge(g.enabled?"enabled":"disabled")}</div>`).join("")}</div>`:"";return `<div class="setup-panel-head"><p class="eyebrow">STEP 4</p><h2>Add Echo to the group, then bind it</h2><p>WhatsApp controls group membership. Echo can discover a group only after its connected account has been added to that group.</p></div><div class="setup-panel-body"><ol class="setup-instructions"><li><span>1</span><div><strong>Add Echo in WhatsApp</strong><p>Open the team group and add the dedicated Echo contact as a participant.</p></div></li><li><span>2</span><div><strong>Return here and discover groups</strong><p>Echo reads the joined group list from its own account.</p></div></li><li><span>3</span><div><strong>Bind the group to ${escapeHTML(s.project?.name||"a project")}</strong><p>Only real @mention metadata in enabled bindings will create incidents.</p></div></li></ol>${bound}${!s.whatsapp?`<div class="setup-warning"><strong>WhatsApp is not connected</strong><p>Complete step 1 before group discovery.</p></div>`:""}${!s.project?`<div class="setup-warning"><strong>No project selected</strong><p>Complete step 2 before binding a group.</p></div>`:""}<div class="setup-actions"><button class="button secondary" id="setup-bind-group" ${!s.whatsapp||!s.project?"disabled":""}>Discover and bind group</button>${s.groups.length?`<button class="button primary" data-setup-step="4">Continue to test</button>`:""}</div></div>`}
function setupTestPanel(s){const incidents=s.project?state.incidents.filter(i=>i.projectId===s.project.id).slice(0,3):[];return `<div class="setup-panel-head"><p class="eyebrow">FINAL CHECK</p><h2>Run a real mention test</h2><p>This checks the same path your partners will use, without granting any deployment authority.</p></div><div class="setup-panel-body"><div class="setup-relations">${setupCheck(s.whatsapp,"WhatsApp account connected",s.whatsapp?"Gateway is online":"Return to step 1")}${setupCheck(Boolean(s.project),"Project selected",s.project?.name||"Return to step 2")}${setupCheck(s.groups.length>0,"Group bound",s.groups.length?`${s.groups[0].groupName} will accept mentions`:"Return to step 4")}${setupCheck(s.repos.length>0,"Repository linked",s.repos.length?"Code-aware diagnosis is available":"Optional for intake testing")}${setupCheck(s.owner,"Owner selected",s.owner?`${state.ownerSettings.displayName||state.ownerSettings.jid} receives private updates`:"Message Echo directly, then select yourself under WhatsApp")}</div>${!s.owner?`<div class="setup-warning"><strong>Select an owner for private updates and approvals</strong><p>Send Echo a direct WhatsApp message, refresh the WhatsApp page, and select your discovered contact as owner.</p><button class="button secondary" data-go="channels">Configure owner</button></div>`:""}${s.intakeReady?`<div class="test-script"><p class="eyebrow">SEND THIS IN ${escapeHTML(s.groups[0].groupName)}</p><blockquote>Tap @, select Echo’s contact, then send: “The lead form is blank after I submit it. It started today on the contact page.”</blockquote><p>Expected: Echo acknowledges in the group, creates an incident, runs available analysis${s.owner?", and sends the owner a private summary":". Private summaries begin after an owner is selected"}.</p></div><div class="setup-actions"><button class="button primary" data-go="incidents">Watch incidents</button><button class="button secondary" id="refresh-test">Refresh results</button></div>`:`<div class="setup-warning"><strong>Message intake is not ready yet</strong><p>Connect WhatsApp, select a project and bind at least one group. Repository access is not required for this first test.</p></div><button class="button primary" data-setup-step="${recommendedIntakeStep()}">Finish required setup</button>`}${incidents.length?`<div class="setup-results"><h3>Latest project incidents</h3>${incidentTable(incidents)}</div>`:""}</div>`}

function renderOverview(){const d=state.dashboard;const recent=state.incidents.slice(0,6);const work=d.queuedJobs+d.runningJobs+d.retryingJobs+d.deadJobs;return `${setupBanner()}<div class="metric-grid">${metric("Open incidents",d.openIncidents,"Reports requiring attention","--blue")}${metric("Open alerts",d.openAlerts,"Runtime conditions requiring attention",d.openAlerts?"--coral":"--mint")}${metric("Pending approvals",d.pendingApprovals,"No action runs without consent","--amber")}${metric("Work queue",work,`${d.queuedJobs} queued · ${d.runningJobs} running · ${d.retryingJobs} retrying · ${d.deadJobs} dead${d.workerQueueStalled?" · STALLED":""}`,(d.deadJobs||d.workerQueueStalled)?"--coral":"--mint")}${metric("Failed deployments",d.failedDeployments,"Across all environments","--coral")}${metric("Active projects",d.enabledProjects,"Group-to-code mappings","--mint")}</div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Recent incidents</h2><p>WhatsApp reports and their current control state</p></div><button class="quiet" data-go="incidents">View all</button></div>${incidentTable(recent)}</section><section class="card"><div class="card-head"><div><h2>Operational posture</h2><p>Trust boundaries at a glance</p></div></div><div class="card-body timeline"><div class="timeline-item"><i></i><div><strong>Service monitoring</strong><p>${d.openAlerts} open alerts across ${state.services.filter(s=>s.enabled).length} enabled services.</p></div></div><div class="timeline-item"><i></i><div><strong>Worker queue</strong><p>${d.queuedJobs} queued, ${d.runningJobs} running, ${d.retryingJobs} retrying, and ${d.deadJobs} dead jobs. ${d.workerQueueStalled?escapeHTML(d.workerHealthSummary)+" ":""}Dead work stays visible for investigation; Echo never retries it blindly.</p></div></div><div class="timeline-item"><i></i><div><strong>WhatsApp gateway</strong><p>${escapeHTML(state.whatsapp.status)} · ${d.pendingWhatsAppMessages} pending and ${d.deadWhatsAppMessages} dead outbound messages. Session messages remain isolated from repository credentials.</p></div></div><div class="timeline-item"><i></i><div><strong>Policy engine</strong><p>${d.pendingApprovals} actions waiting. Production always requires a separate exact-action approval.</p></div></div><div class="timeline-item"><i></i><div><strong>Repository access</strong><p>${state.repos.filter(r=>r.enabled).length} enabled repositories, ${state.repos.filter(r=>r.readOnly).length} read-only.</p></div></div><div class="timeline-item"><i></i><div><strong>Audit coverage</strong><p>${state.audit.length} recent immutable events available for review.</p></div></div></div></section></div>`}
function metric(label,value,note,accent){return `<article class="metric accent-${escapeHTML(accent.replace("--",""))}"><small>${label}</small><strong>${value}</strong><span>${note}</span></article>`}
function incidentTable(items){if(!items.length)return empty("No incidents yet","Mention Echo in a configured WhatsApp group to create one.");return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Incident</th><th>Project</th><th>Status</th><th>Severity</th><th>Reported</th></tr></thead><tbody>${items.map(i=>`<tr data-incident="${i.id}"><td><span class="primary-text">${escapeHTML(i.summary)}</span><span class="secondary-text">${i.id} · ${escapeHTML(i.reporterName||i.reporterJid)}</span></td><td>${escapeHTML(i.projectName)}</td><td>${badge(i.status)}</td><td><span class="priority ${i.severity}">${escapeHTML(i.severity)}</span></td><td>${when(i.createdAt)}</td></tr>`).join("")}</tbody></table></div>`}

function renderIncidents(){const filtered=state.incidentFilter?state.incidents.filter(i=>i.status===state.incidentFilter):state.incidents;return `<div class="toolbar"><p>${filtered.length} of ${state.incidents.length} reports shown.</p><div class="filter-row"><select id="incident-filter"><option value="">All states</option>${["reported","triaging","awaiting_owner","change_approved","patching","staging","staging_verified","production","resolved","failed"].map(v=>`<option value="${v}" ${state.incidentFilter===v?"selected":""}>${v.replaceAll("_"," ")}</option>`).join("")}</select></div></div><section class="card" id="incident-list">${incidentTable(filtered)}</section>`}
async function openIncident(id){
  try{
    const data=await api(`/api/v1/incidents/${id}`);
    const i=data.incident,a=data.analysis,changes=data.changeSets||[],deployments=data.deployments||[],attachments=data.attachments||[],messages=data.messages||[];
    const followUpCount=Math.max(0,(i.evidenceRevision||1)-1);
    const latest=changes[0];
    const projectRepos=state.repos.filter(r=>r.projectId===i.projectId&&r.enabled);
    const writableRepos=projectRepos.filter(r=>!r.readOnly);
    const proposedName=(a?.proposal?.repository||"").toLowerCase();
    const proposedRepo=projectRepos.find(r=>`${r.owner}/${r.name}`.toLowerCase()===proposedName)||(projectRepos.length===1?projectRepos[0]:null);
    const staging=state.environments.find(e=>e.projectId===i.projectId&&e.name.toLowerCase()==="staging");
    const production=state.environments.find(e=>e.projectId===i.projectId&&e.name.toLowerCase()==="production");
    const proposal=a?.proposal;
    const mergeApproval=state.approvals.find(item=>item.incidentId===i.id&&item.actionType==="merge_production"&&["pending","approved"].includes(item.status));
    const productionDeployment=deployments.find(item=>item.environment==="production");
    const proposalDetails=proposal?`<div class="risk"><b>Proposed action</b><p>${escapeHTML(proposal.description||proposal.action||"Review required")}</p>${(proposal.risks||[]).length?`<b>Risks</b><ul>${proposal.risks.map(v=>`<li>${escapeHTML(v)}</li>`).join("")}</ul>`:""}${(proposal.tests||[]).length?`<b>Validation</b><ul>${proposal.tests.map(v=>`<li>${escapeHTML(v)}</li>`).join("")}</ul>`:""}</div>`:"";
    let patchControl="";
    if(a&&!latest){
      if(writableRepos.length){
        patchControl=`<button class="button primary full" data-request-patch="${i.id}">Request patch approval</button><p class="muted">This creates a one-time approval request. Echo sends explicit APPROVE and REJECT reply options to the owner; no code changes happen until approval.</p>`;
      }else if(proposedRepo?.readOnly){
        patchControl=`<div class="setup-warning"><strong>Patch preparation is locked</strong><p>${escapeHTML(proposedRepo.owner)}/${escapeHTML(proposedRepo.name)} is read-only. Enable approved changes only if you want Echo to create a draft fix.</p></div><button class="button secondary full" data-edit-repository="${proposedRepo.id}">Review repository access</button>`;
      }else{
        patchControl=`<div class="setup-warning"><strong>No write-gated repository</strong><p>Configure the proposed repository before Echo can prepare a draft patch.</p></div><button class="button secondary full" data-go="repositories">Open repositories</button>`;
      }
    }
    let repositoryProduction="";
    if(latest&&!staging&&!productionDeployment){
      if(mergeApproval?.status==="pending")repositoryProduction=`<div class="setup-warning"><strong>Production approval requested</strong><p>Check WhatsApp for the one-time APPROVE or REJECT command.</p></div>`;
      else if(mergeApproval?.status==="approved"||i.status==="production")repositoryProduction=`<div class="setup-callout"><strong>Merge and production deployment in progress</strong><p>Echo is monitoring the repository's existing main-branch workflow and will report the verified result.</p></div>`;
      else if(["testing","ready"].includes(latest.status))repositoryProduction=`<div class="setup-warning"><strong>This project has no staging environment</strong><p>The separate production approval will verify GitHub checks, merge only commit ${escapeHTML(latest.commitSha.slice(0,12))}, and monitor the repository's existing main-branch deployment workflow.</p></div><button class="button danger full" data-request-merge="${i.id}" data-change-set="${latest.id}">Request merge and production deploy</button>`;
    }
    if(productionDeployment)repositoryProduction=`<div class="setup-${productionDeployment.status==="verified"?"success compact":"callout"}"><div><strong>Production ${escapeHTML(productionDeployment.status)}</strong><p>${escapeHTML(productionDeployment.artifactRef)}${productionDeployment.workflowUrl?` · <a href="${escapeHTML(productionDeployment.workflowUrl)}" target="_blank" rel="noreferrer">workflow run</a>`:""}</p></div></div>`;
    openModal("INCIDENT",id,`<div class="detail-grid"><div><p class="eyebrow">INCIDENT THREAD</p><div class="setup-list">${messages.length?messages.map(item=>{const original=item.whatsappMessageId===i.sourceMessageId;return `<div><span class="setup-list-icon">${original?"●":"↳"}</span><p><strong>${escapeHTML(item.senderName||"Group participant")}</strong><small>${when(item.messageTimestamp)}</small><span>${escapeHTML(item.body)}</span></p>${badge(original?"original report":"follow-up")}</div>`}).join(""):`<div class="report">${escapeHTML(i.sourceBody)}</div>`}</div>${attachments.length?`<div class="setup-list">${attachments.map(item=>`<div><span class="setup-list-icon">▧</span><p><strong>${escapeHTML(item.fileName||"WhatsApp screenshot")}</strong><small>${escapeHTML(item.mimeType)} · ${Math.ceil(item.sizeBytes/1024)} KiB · SHA-256 ${escapeHTML(item.sha256.slice(0,12))}…</small></p>${badge("retained evidence")}</div>`).join("")}</div>`:""}<hr><p class="eyebrow">LATEST ANALYSIS</p>${a?`<h3>${escapeHTML(a.summary)}</h3><p class="muted">Evidence revision ${a.evidenceRevision||1} · Confidence: ${escapeHTML(a.confidence)} · ${when(a.createdAt)}</p><div class="evidence-list">${(a.evidence||[]).map(e=>`<div class="evidence"><code>${escapeHTML(e.repository)} · ${escapeHTML(e.path)}</code><p>${escapeHTML(e.finding)}</p></div>`).join("")||empty("No direct evidence","Echo needs more operational detail.")}</div>`:empty("Analysis queued","The worker has not completed repository analysis yet.")}${latest?`<hr><p class="eyebrow">CHANGE SET</p><a href="${escapeHTML(latest.pullRequestUrl)}" target="_blank" rel="noreferrer">Pull request #${latest.pullRequestNumber}</a><p class="muted">${escapeHTML(latest.commitSha)} · ${escapeHTML(latest.status)}</p>`:""}</div><div><div class="card-body"><p class="eyebrow">CONTROL STATE</p><p>${badge(i.status)} ${badge(i.severity)}</p><dl><dt>Project</dt><dd>${escapeHTML(i.projectName)}</dd><dt>Reporter</dt><dd>${escapeHTML(i.reporterName||i.reporterJid)}</dd><dt>Reported</dt><dd>${when(i.createdAt)}</dd><dt>Evidence revision</dt><dd>${i.evidenceRevision||1}</dd><dt>Follow-ups</dt><dd>${followUpCount}</dd><dt>Screenshot evidence</dt><dd>${attachments.length}</dd></dl>${proposalDetails}${patchControl}${latest&&staging?`<button class="button primary full" data-request-deploy="${i.id}" data-environment="${staging.id}" data-artifact="${latest.artifactRef}" data-kind="deploy_staging">Request staging</button>`:""}${i.status==="staging_verified"&&latest&&production?`<button class="button danger full" data-request-deploy="${i.id}" data-environment="${production.id}" data-artifact="${latest.artifactRef}" data-kind="deploy_production">Request production</button>`:""}${repositoryProduction}<p class="muted">${deployments.length} deployment records</p></div></div></div>`);
  }catch(err){toast(err.message)}
}

function approvalDescription(a){const action=a.action||{};if(a.actionType==="merge_production")return `${action.repositoryFullName||"repository"} · PR #${action.pullRequestNumber||"?"} · commit ${String(action.headSha||"").slice(0,12)}`;if(a.actionType==="prepare_patch")return action.repositoryFullName||action.repository||`Action ${a.actionHash.slice(0,12)}`;if(a.actionType.startsWith("deploy_"))return `${a.actionType.replace("deploy_","")} · commit ${String(action.artifactRef||"").slice(0,12)}`;return `Action ${a.actionHash.slice(0,12)}`}
function renderApprovals(){const pending=state.approvals.filter(a=>a.status==="pending");return `<div class="toolbar"><p>Each approval is bound to an incident, exact action, actor, and expiry.</p></div><section class="card">${state.approvals.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Action</th><th>Incident</th><th>Requested by</th><th>Expires</th><th>Status</th><th></th></tr></thead><tbody>${state.approvals.map(a=>`<tr><td><span class="primary-text">${escapeHTML(a.actionType.replaceAll("_"," "))}</span><span class="secondary-text">${escapeHTML(approvalDescription(a))}</span></td><td>${escapeHTML(a.incidentId)}</td><td>${escapeHTML(a.requestedBy)}</td><td>${when(a.expiresAt)}</td><td>${badge(a.status)}</td><td>${a.status==="pending"?`<button class="button primary" data-approval="${a.id}" data-resolution="approved">Approve</button> <button class="button danger" data-approval="${a.id}" data-resolution="rejected">Reject</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:empty("No approval history","Approval requests will appear here before any code or deployment action.")}</section>${pending.length?`<p class="risk">Approving authorizes only the exact repository, pull request and commit shown. It does not grant open-ended repository or deployment access.</p>`:""}`}

function renderProjects(){return `<div class="toolbar"><p>A project is the hub that connects a team’s WhatsApp groups, code and deployment environments.</p><button class="button primary" id="add-project">Add project</button></div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Configured projects</h2><p>${state.projects.filter(p=>p.enabled).length} enabled</p></div></div>${state.projects.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>State</th><th>Repositories</th><th>Groups</th><th>Setup</th></tr></thead><tbody>${state.projects.map(p=>{const repos=state.repos.filter(r=>r.projectId===p.id&&r.enabled).length;const groups=state.groups.filter(g=>g.projectId===p.id&&g.enabled).length;return `<tr data-project-setup="${p.id}"><td><span class="primary-text">${escapeHTML(p.name)}</span><span class="secondary-text">${escapeHTML(p.description||p.key)}</span></td><td>${badge(p.enabled?"enabled":"disabled")}</td><td>${repos}</td><td>${groups}</td><td>${badge(repos&&groups?"ready":"incomplete")}</td></tr>`}).join("")}</tbody></table></div>`:empty("No projects","Use Guided setup to create the first project, link its code and bind its group.")}</section><section class="card"><div class="card-head"><div><h2>How projects work</h2><p>The relationships Echo follows for every report</p></div><button class="quiet" data-resume-setup>Open guide</button></div><div class="card-body timeline"><div class="timeline-item"><i></i><div><strong>WhatsApp group → project</strong><p>Each bound group routes mentions into one project. A project may have multiple groups.</p></div></div><div class="timeline-item"><i></i><div><strong>Project → code graph</strong><p>Link the application, shared base, plugins and infrastructure Echo may inspect.</p></div></div><div class="timeline-item"><i></i><div><strong>Project → environments</strong><p>Staging and production remain separate, approval-gated delivery targets.</p></div></div></div></section></div>`}

function intakeReason(reason){return({echo_not_mentioned:"Echo received the message, but WhatsApp did not mark Echo as mentioned.",echo_identity_unavailable:"Echo received the message before its linked-device identity was ready.",binding_disabled:"Echo received the message, but this group binding is disabled.",empty_message:"Echo received a message type with no supported text or caption.",not_a_group_message:"The message was not a group report."})[reason]||String(reason||"Message rejected by intake policy.").replaceAll("_"," ")}
function latestIntakeEvent(){return state.audit.find(a=>["incident.reported","message.ignored"].includes(a.action))}
function intakeDetails(a){if(!a)return"";const metadata=a.metadata&&typeof a.metadata==="object"?a.metadata:{};if(a.action==="message.ignored")return intakeReason(metadata.reason);if(a.action==="incident.reported")return"Accepted and created an incident.";return""}
function contactLabel(contact){return contact.displayName?`${contact.displayName} · ${contact.jid}`:contact.jid}
function ownerCard(){const owner=state.ownerSettings;const discovered=state.contacts.slice(0,5);return `<section class="card owner-card"><div class="card-head"><div><h2>Owner contact</h2><p>Private diagnoses, approval codes and deployment results go only to this person</p></div>${owner?.configured?badge("configured"):badge("required")}</div><div class="card-body">${owner?.configured?`<div class="setup-success compact"><span>✓</span><div><strong>${escapeHTML(owner.displayName||owner.jid)}</strong><p>${escapeHTML(owner.jid)} · ${owner.source==="application"?"selected in Echo":"environment fallback"}</p></div></div>`:`<div class="setup-warning"><strong>No owner selected</strong><p>Send Echo a direct WhatsApp message first. Echo will confirm discovery, then the contact will appear here.</p></div>`}${discovered.length?`<div class="setup-list">${discovered.map(c=>`<div><span class="setup-list-icon">●</span><p><strong>${escapeHTML(c.displayName||c.jid)}</strong><small>${escapeHTML(c.jid)} · ${c.messageCount} direct ${c.messageCount===1?"message":"messages"} · last seen ${when(c.lastSeenAt)}</small></p>${c.id===owner?.contactId?badge("owner"):""}</div>`).join("")}</div>`:`<p class="muted">No direct-message contacts discovered yet. Group participants are deliberately not collected.</p>`}<div class="setup-actions"><button class="button ${owner?.configured?"secondary":"primary"}" id="configure-owner" ${discovered.length?"":"disabled"}>${owner?.configured?"Change owner":"Select owner"}</button>${owner?.source==="application"?`<button class="button danger" id="clear-owner">Clear owner</button>`:""}<button class="quiet" id="refresh-contacts">Refresh contacts</button></div></div></section>`}
function briefingCard(){const briefing=state.briefingSettings||{};const enabled=Boolean(briefing.enabled);const destination=state.ownerSettings?.configured?state.ownerSettings.displayName||state.ownerSettings.jid:"No owner selected";return `<section class="card"><div class="card-head"><div><h2>Daily briefing</h2><p>One proactive operational summary per local day through the durable outbox</p></div>${badge(enabled?"enabled":"disabled")}</div><div class="card-body"><div class="feature-grid"><div class="feature"><strong>Schedule</strong><p>${enabled?`${escapeHTML(briefing.localTime)} · ${escapeHTML(briefing.timezone)}`:"Off"}</p></div><div class="feature"><strong>Destination</strong><p>${escapeHTML(destination)}</p></div><div class="feature"><strong>Last queued</strong><p>${briefing.lastSentAt?when(briefing.lastSentAt):"Not yet sent"}</p></div><div class="feature"><strong>Delivery rule</strong><p>At most once per local date, even after restart</p></div></div>${enabled&&!state.ownerSettings?.configured?`<div class="setup-warning"><strong>Waiting for an owner</strong><p>The schedule is retained, but Echo will not render or queue a briefing until an owner is configured.</p></div>`:""}<div class="setup-actions"><button class="button ${enabled?"secondary":"primary"}" id="configure-briefing">${enabled?"Change schedule":"Enable daily brief"}</button></div></div></section>`}
function intakeDiagnosticCard(){const event=latestIntakeEvent();return `<section class="card intake-diagnostic"><div class="card-head"><div><h2>Last message intake result</h2><p>Confirms whether Echo received and accepted the latest relevant group message</p></div><button class="quiet" id="refresh-intake">Refresh</button></div><div class="card-body">${event?`<div class="setup-${event.action==="incident.reported"?"success compact":"warning"}">${event.action==="incident.reported"?"<span>✓</span>":""}<div><strong>${event.action==="incident.reported"?"Report accepted":"Message received but ignored"}</strong><p>${escapeHTML(intakeDetails(event))} · ${when(event.createdAt)}</p></div></div>`:`<div class="setup-callout"><strong>No bound-group message has been observed yet</strong><p>Send a new message by tapping @ and selecting Echo’s contact, then refresh. Echo will now show an explicit result here if intake policy rejects it.</p></div>`}</div></section>`}
function renderChannels(){const w=state.whatsapp;const waiting=["pairing_requested","pairing","connecting"].includes(w.status);const session=w.qrCode?`<div class="qr-box" aria-live="polite"><p>Open WhatsApp on the dedicated number, then choose <b>Linked devices → Link a device</b>.</p><img src="/api/v1/whatsapp/qr.png?v=${encodeURIComponent(w.updatedAt||Date.now())}" alt="Fresh WhatsApp pairing QR code"><p class="muted">Echo automatically replaces this image when WhatsApp rotates the code. Treat it as a secret.</p></div>`:w.status==="connected"?`<div class="feature-grid"><div class="feature"><strong>Device identity</strong><p>${escapeHTML(w.deviceJid||"Connected")}</p></div><div class="feature"><strong>Last event</strong><p>${escapeHTML(w.lastEvent||"connected")}</p></div><div class="feature"><strong>Connected</strong><p>${when(w.connectedAt)}</p></div><div class="feature"><strong>Last error</strong><p>${escapeHTML(w.lastError||"None")}</p></div></div>`:`<div class="link-device"><h3>${waiting?"Preparing a fresh pairing code":"Link the dedicated Echo number"}</h3><p class="muted">A code is generated only when you request one, so an old code is never left waiting on this screen.</p>${w.lastError?`<p class="form-error">${escapeHTML(w.lastError)}</p>`:""}<button class="button primary" id="link-device" ${waiting?"disabled":""}>${waiting?"Preparing…":"Link device"}</button></div>`;return `<div class="grid-2"><section class="card"><div class="card-head"><div><h2>WhatsApp session</h2><p>HyperMeow connection backed by isolated MariaDB state</p></div>${badge(w.status)}</div><div class="card-body">${session}</div></section><section class="card"><div class="card-head"><div><h2>Group bindings</h2><p>Only real mention metadata opens an incident</p></div><button class="button primary" id="add-group">Bind group</button></div>${state.groups.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Group</th><th>Project</th><th>Mention</th><th>State</th></tr></thead><tbody>${state.groups.map(g=>`<tr><td><span class="primary-text">${escapeHTML(g.groupName)}</span><span class="secondary-text">${escapeHTML(g.groupJid)}</span></td><td>${escapeHTML(g.projectName)}</td><td>${g.mentionRequired?"Required":"Any message"}</td><td>${badge(g.enabled?"enabled":"disabled")}</td></tr>`).join("")}</tbody></table></div>`:empty("No group bindings","Pair Echo, add it to a group, then bind that group JID to a project.")}</section></div><div class="grid-2">${ownerCard()}${briefingCard()}</div>${intakeDiagnosticCard()}`}

function repositoryWorkflowAlertPanel(){return `<section class="card"><div class="card-head"><div><h2>Default-branch workflow attention</h2><p>Persisted by the supervised read-only GitHub watchdog</p></div>${badge(`${state.workflowAlerts.length} open`)}</div><div class="setup-list">${state.workflowAlerts.map(alert=>`<div><span class="setup-list-icon">!</span><p><strong>${escapeHTML(alert.repository)}</strong><small>${escapeHTML(alert.summary)} · failed: ${escapeHTML((alert.failedWorkflows||[]).join(", "))} · last seen ${when(alert.lastSeenAt)}</small></p>${badge("critical")}</div>`).join("")}</div></section>`}
function renderRepositories(){const connected=Boolean(state.githubSettings?.configured);return `<div class="github-connection ${connected?"connected":"missing"}"><div><p class="eyebrow">GITHUB CONNECTION</p><h2>${connected?`Connected as ${escapeHTML(state.githubSettings.account||"GitHub user")}`:"Token not configured"}</h2><p>${connected?`The token is encrypted at rest · updated ${when(state.githubSettings.updatedAt)}.`:"Add a fine-grained token limited to the repositories Echo may inspect."}</p></div><div class="setup-actions"><button class="button ${connected?"secondary":"primary"}" id="configure-github-token">${connected?"Replace token":"Configure token"}</button>${connected?`<button class="button danger" id="remove-github-token">Remove</button>`:""}</div></div><div class="toolbar"><p>Discover only repositories visible to the connected token, or enter one manually.</p><div class="setup-actions"><button class="button secondary" id="discover-github-repos" ${connected?"":"disabled"}>Discover from GitHub</button><button class="button primary" id="add-repo" ${connected?"":"disabled"}>Enter manually</button></div></div><section class="card">${state.repos.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Repository</th><th>Project</th><th>Role</th><th>Access</th><th>Branch</th><th>State</th></tr></thead><tbody>${state.repos.map(r=>`<tr data-repository="${r.id}"><td><span class="primary-text">${escapeHTML(r.owner)}/${escapeHTML(r.name)}</span><span class="secondary-text">Click to edit access</span></td><td>${escapeHTML(state.projects.find(p=>p.id===r.projectId)?.name||r.projectId)}</td><td>${badge(r.role)}</td><td>${badge(r.readOnly?"read only":"approved changes")}</td><td><code>${escapeHTML(r.defaultBranch)}</code></td><td>${badge(r.enabled?"enabled":"disabled")}</td></tr>`).join("")}</tbody></table></div>`:empty("No repositories",connected?"Discover a repository from the token scope and link it read-only first.":"Configure a GitHub token first, then link selected repositories.")}</section><p class="risk">Use a fine-grained token limited to selected repositories. Discovery reads only repository identity, default branch, visibility, archive/fork state, and coarse write permission. Newly linked repositories default to read-only. Approved patching and merging need Contents: write and Pull requests: write. Existing-workflow monitoring needs Actions: read; Echo-dispatched workflows need Actions: write.</p>`}

function renderMonitoring(){
  const now=Date.now();
  const activeMaintenance=state.maintenance.filter(window=>new Date(window.startsAt).getTime()<=now&&new Date(window.endsAt).getTime()>now);
  const suppressedServices=new Set(activeMaintenance.map(window=>window.serviceId));
  const openCritical=state.alerts.filter(a=>a.severity==="critical"&&!a.acknowledgedAt&&!suppressedServices.has(a.serviceId)).length;
  const actionable=state.alerts.filter(a=>!a.acknowledgedAt&&!suppressedServices.has(a.serviceId)).length;
  const alertRows=state.alerts.map(a=>{const window=activeMaintenance.find(item=>item.serviceId===a.serviceId);const until=window?.endsAt||a.notificationSuppressedUntil;const suppressed=until&&new Date(until).getTime()>now;return `<tr data-service="${escapeHTML(a.serviceId)}" tabindex="0" role="button"><td><span class="primary-text">${escapeHTML(a.serviceName)}</span>${suppressed?`<span class="secondary-text">Maintenance suppression until ${when(until)}</span>`:a.acknowledgedAt?`<span class="secondary-text">Acknowledged ${when(a.acknowledgedAt)} · ${Number(a.reminderCount||0)} reminder(s)</span>`:""}</td><td>${badge(a.severity)} ${suppressed?badge("maintenance"):a.acknowledgedAt?badge("acknowledged"):""}</td><td>${escapeHTML(a.summary)}</td><td>${when(a.lastSeenAt)}</td><td><button class="quiet" data-alert-acknowledgement="${escapeHTML(a.id)}" data-acknowledged="${a.acknowledgedAt?"true":"false"}">${a.acknowledgedAt?"Clear acknowledgement":"Acknowledge"}</button></td></tr>`}).join("");
  const signalRows=state.monitorEvents.slice(0,20).map(e=>`<tr data-service="${escapeHTML(e.serviceId)}" tabindex="0" role="button"><td><span class="primary-text">${escapeHTML(e.serviceName)}</span><span class="secondary-text">${escapeHTML(e.summary)}</span></td><td>${badge(e.status)}</td><td>${escapeHTML(e.source)}</td><td>${when(e.observedAt)}</td></tr>`).join("");
  const serviceRows=state.services.map(s=>{const window=activeMaintenance.find(item=>item.serviceId===s.id);return `<tr data-service="${escapeHTML(s.id)}" tabindex="0" role="button"><td><span class="primary-text">${escapeHTML(s.name)}</span><span class="secondary-text">${escapeHTML(s.key)} · ${escapeHTML(s.description||"No description")}</span></td><td>${escapeHTML(s.projectName||s.projectId)}</td><td>${badge(s.kind)}</td><td>${badge(s.criticality)}</td><td>${escapeHTML(durationSeconds(s.heartbeatTimeoutSeconds))}</td><td>${badge(window?"maintenance":s.enabled?"enabled":"disabled")}</td></tr>`}).join("");
  const maintenanceRows=state.maintenance.map(window=>{const active=new Date(window.startsAt).getTime()<=now;return `<tr><td><span class="primary-text">${escapeHTML(window.serviceName)}</span><span class="secondary-text">${escapeHTML(window.reason)}</span></td><td>${badge(active?"active":"upcoming")}</td><td>${when(window.startsAt)}</td><td>${when(window.endsAt)}</td><td><button class="quiet" data-cancel-maintenance="${escapeHTML(window.id)}">Cancel</button></td></tr>`}).join("");
  return `<div class="metric-grid">${metric("Open alerts",state.alerts.length,actionable?`${actionable} need attention`:state.alerts.length?"Suppressed or acknowledged":"All clear",actionable?"--amber":"--mint")}${metric("Unacknowledged critical",openCritical,openCritical?"Bounded reminders remain active":"None",openCritical?"--rose":"--mint")}${metric("Maintenance",activeMaintenance.length,`${state.maintenance.length-activeMaintenance.length} upcoming`,activeMaintenance.length?"--amber":"--mint")}${metric("Services",state.services.filter(s=>s.enabled).length,"Enabled catalogue entries","--blue")}${metric("Monitor intake",state.bootstrap.features.monitor?"enabled":"disabled",state.bootstrap.features.monitor?"Signed webhook active":"Configure webhook secret",state.bootstrap.features.monitor?"--mint":"--amber")}</div><div class="toolbar"><p>Select any service, alert, or signal to inspect its evidence and freshness.</p><div class="setup-actions"><button class="button secondary" data-schedule-maintenance ${state.services.some(s=>s.enabled)?"":"disabled"}>Schedule maintenance</button><button class="button primary" id="add-service">Add service</button></div></div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Open alerts</h2><p>Critical alerts remind the owner until acknowledged, resolved, or placed in bounded maintenance</p></div></div>${state.alerts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Severity</th><th>Summary</th><th>Last seen</th><th></th></tr></thead><tbody>${alertRows}</tbody></table></div>`:empty("No open alerts","Echo will show degraded and unhealthy service signals here.")}</section><section class="card"><div class="card-head"><div><h2>Recent signals</h2><p>Evidence continues during planned maintenance</p></div></div>${state.monitorEvents.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Status</th><th>Source</th><th>Observed</th></tr></thead><tbody>${signalRows}</tbody></table></div>`:empty("No signals yet","Connect a local observer after adding the first service.")}</section></div><section class="card"><div class="card-head"><div><h2>Planned maintenance</h2><p>Notifications pause only for the selected service and exact UTC-backed window</p></div><button class="quiet" data-schedule-maintenance>Schedule</button></div>${maintenanceRows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>State</th><th>Starts</th><th>Ends</th><th></th></tr></thead><tbody>${maintenanceRows}</tbody></table></div>`:empty("No planned maintenance","Unexpected unhealthy evidence will notify the owner normally.")}</section><section class="card"><div class="card-head"><div><h2>Service catalogue</h2><p>The stable map between projects and runtime workloads</p></div></div>${state.services.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Project</th><th>Kind</th><th>Criticality</th><th>Heartbeat</th><th>State</th></tr></thead><tbody>${serviceRows}</tbody></table></div>`:empty("No services","Add a service to give monitoring and investigations a stable operational target.")}</section>`
}

function serviceFreshness(service,events){
  if(!service.enabled)return{state:"disabled",detail:"Monitoring intake is disabled for this service."};
  if(!service.heartbeatTimeoutSeconds)return{state:"not enforced",detail:"Missing observer evidence does not currently open an alert."};
  const latest=events.find(event=>event.source!=="echo-watchdog");
  if(!latest)return{state:"missing",detail:`No observer evidence received; expected within ${durationSeconds(service.heartbeatTimeoutSeconds)}.`};
  const ageSeconds=Math.max(0,Math.floor((Date.now()-new Date(latest.observedAt).getTime())/1000));
  const stale=ageSeconds>service.heartbeatTimeoutSeconds;
  return{state:stale?"stale":"fresh",detail:`Last observer report ${elapsedSeconds(ageSeconds)} ago; expected within ${durationSeconds(service.heartbeatTimeoutSeconds)}.`};
}

function signalEvidence(details){
  let value=details;
  if(typeof value==="string"){try{value=JSON.parse(value)}catch{return"No structured evidence"}}
  if(!value||typeof value!=="object"||Array.isArray(value))return"No structured evidence";
  const lines=[];
  const visit=(object,prefix,depth)=>Object.entries(object).forEach(([key,item])=>{
    if(lines.length>=24)return;
    if(item&&typeof item==="object"&&!Array.isArray(item)&&depth<2){visit(item,`${prefix}${key}.`,depth+1);return}
    if(item===null||["string","number","boolean"].includes(typeof item)){
      const rendered=typeof item==="string"?item:JSON.stringify(item);
      lines.push(`${prefix}${key}: ${String(rendered).slice(0,300)}`)
    }
  });
  visit(value,"",0);
  return lines.length?lines.join("\n")+(lines.length===24?"\n…additional evidence omitted":""):"No structured evidence";
}

async function openService(serviceId){
  const service=state.services.find(item=>item.id===serviceId);
  if(!service){toast("Service is no longer available");return}
  state.openServiceId=service.id;
  const events=await api(`/api/v1/monitor/events?serviceId=${encodeURIComponent(service.id)}&limit=10`)||[];
  const alerts=state.alerts.filter(alert=>alert.serviceId===service.id);
  const dependencies=state.dependencies.filter(item=>item.serviceId===service.id||item.dependsOnServiceId===service.id);
  const runbooks=state.runbooks.filter(item=>item.serviceId===service.id);
  const freshness=serviceFreshness(service,events);
  const alertView=alerts.length?`<div class="setup-list">${alerts.map(alert=>`<div><span class="setup-list-icon">!</span><p><strong>${escapeHTML(alert.summary)}</strong><small>${escapeHTML(alert.fingerprint)} · opened ${when(alert.openedAt)} · last seen ${when(alert.lastSeenAt)}${alert.acknowledgedAt?` · acknowledged ${when(alert.acknowledgedAt)}`:""}</small></p>${badge(alert.severity)} ${alert.acknowledgedAt?badge("acknowledged"):""}</div>`).join("")}</div>`:empty("No open alerts","Recent healthy evidence has cleared all active conditions for this service.");
  const signalView=events.length?`<div class="setup-list">${events.slice(0,10).map(event=>`<div><span class="setup-list-icon">•</span><div><p><strong>${escapeHTML(event.summary)}</strong><small>${escapeHTML(event.source)} · ${when(event.observedAt)}</small></p><details><summary>Evidence</summary><pre class="report">${escapeHTML(signalEvidence(event.details))}</pre></details></div>${badge(event.status)}</div>`).join("")}</div>`:empty("No signals received","Start the configured observer and confirm its service ID and webhook secret.");
  const dependencyView=dependencies.length?`<div class="setup-list">${dependencies.map(item=>{const outgoing=item.serviceId===service.id;const name=outgoing?item.dependsOnServiceName:item.serviceName;return `<div><span class="setup-list-icon">→</span><p><strong>${outgoing?"Depends on":"Used by"} ${escapeHTML(name)}</strong><small>${escapeHTML(item.kind)}${item.description?` · ${escapeHTML(item.description)}`:""}</small></p><button class="quiet" data-delete-dependency="${escapeHTML(item.id)}">Remove</button></div>`}).join("")}</div>`:empty("No declared dependencies","Add the databases, queues, gateways, workers, or external services that directly affect this workload.");
  const runbookView=runbooks.length?`<div class="setup-list">${runbooks.map(item=>`<div><span class="setup-list-icon">?</span><div><p><strong>${escapeHTML(item.title)}</strong><small>${escapeHTML(item.guidance)}</small></p>${item.referenceUrl?`<a href="${escapeHTML(item.referenceUrl)}" target="_blank" rel="noopener noreferrer">Open HTTPS reference</a>`:""}</div><div class="setup-actions"><button class="quiet" data-edit-runbook="${escapeHTML(item.id)}">Edit</button><button class="quiet" data-delete-runbook="${escapeHTML(item.id)}">Remove</button></div></div>`).join("")}</div>`:empty("No operational runbooks","Add concise checks that Echo can use as untrusted reference material during an investigation.");
  const canAddDependency=state.services.some(item=>item.projectId===service.projectId&&item.id!==service.id);
  openModal("SERVICE EVIDENCE",`${service.name} · ${service.key}`,`<div class="setup-success compact"><span>◎</span><div><strong>Observer freshness: ${escapeHTML(freshness.state)}</strong><p>${escapeHTML(freshness.detail)}</p></div></div><div class="setup-actions"><button class="button secondary" data-edit-service="${escapeHTML(service.id)}">Edit service policy</button><button class="button secondary" data-schedule-maintenance="${escapeHTML(service.id)}">Schedule maintenance</button><button class="button secondary" data-add-dependency="${escapeHTML(service.id)}" ${canAddDependency?"":"disabled"}>Add dependency</button><button class="button secondary" data-add-runbook="${escapeHTML(service.id)}">Add runbook</button></div><h3>Declared topology</h3>${dependencyView}<h3>Operational runbooks</h3>${runbookView}<p class="risk">Runbooks are untrusted reference material. Do not store secrets; Echo never executes their steps automatically.</p><h3>Open alerts</h3>${alertView}<h3>Recent signals</h3>${signalView}`)
}

function renderAssistant(){return `<div class="github-connection ${state.aiSettings?.configured?"connected":"missing"}"><div><p class="eyebrow">WHATSAPP INVESTIGATIONS</p><h2>${state.aiSettings?.configured?`AI tools enabled · ${escapeHTML(state.aiSettings.model)}`:"Deterministic commands only"}</h2><p>${state.aiSettings?.configured?"Natural questions can use bounded read-only tools. Responses are stored locally with tool evidence; OpenAI response storage is disabled.":"Configure OpenAI under System to enable natural investigations. Status, alerts, services, projects and incident commands still work."}</p></div><button class="button secondary" data-go="system">AI settings</button></div><section class="card"><div class="card-head"><div><h2>Owner conversations</h2><p>Private WhatsApp turns and their auditable read-tool activity</p></div></div>${state.conversations.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Channel</th><th>Participant</th><th>Started</th><th>Updated</th><th></th></tr></thead><tbody>${state.conversations.map(c=>`<tr><td>${badge(c.channel)}</td><td class="primary-text">${escapeHTML(c.participantKey)}</td><td>${when(c.createdAt)}</td><td>${when(c.updatedAt)}</td><td><button class="quiet" data-conversation="${escapeHTML(c.id)}">Inspect</button></td></tr>`).join("")}</tbody></table></div>`:empty("No owner conversations","Message Echo directly from the configured owner account. Duplicate WhatsApp message IDs are ignored.")}</section><p class="risk">Questions expose no shell, SSH, deployment, or mutation tool. Conversation messages expire according to ECHO_ASSISTANT_RETENTION.</p>`}

function renderEnvironments(){return `<div class="toolbar"><p>Protected environments dispatch CI workflows with immutable artifact references.</p><button class="button primary" id="add-environment">Add environment</button></div><section class="card">${state.environments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Environment</th><th>Project</th><th>Adapter</th><th>Approval</th><th>Protection</th></tr></thead><tbody>${state.environments.map(e=>`<tr><td class="primary-text">${escapeHTML(e.name)}</td><td>${escapeHTML(state.projects.find(p=>p.id===e.projectId)?.name||e.projectId)}</td><td>${badge(e.kind)}</td><td>${e.requiresApproval?"Required":"Disabled"}</td><td>${badge(e.protected?"protected":"unprotected")}</td></tr>`).join("")}</tbody></table></div>`:empty("No environments","Configure staging first, then production with a separate protected workflow.")}</section>`}
function renderDeployments(){return `<div class="toolbar"><p>Only explicitly approved, immutable artifacts are dispatched.</p></div><section class="card">${state.deployments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Operation</th><th>Environment</th><th>Incident</th><th>Artifact</th><th>Status</th><th>Created</th></tr></thead><tbody>${state.deployments.map(d=>`<tr><td>${badge(d.operation||"deploy")}</td><td class="primary-text">${escapeHTML(d.environment)}</td><td>${escapeHTML(d.incidentId)}</td><td><code>${escapeHTML((d.artifactRef||"").slice(0,18))}…</code></td><td>${badge(d.status)}</td><td>${when(d.createdAt)}</td></tr>`).join("")}</tbody></table></div>`:empty("No deployments","Staging, production, and rollback dispatches will appear here with verification results.")}</section>`}

function renderAudit(){return `<div class="toolbar"><p>Recent security-relevant state transitions and external mutations.</p></div><section class="card">${state.audit.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Resource</th><th>Details</th><th>Outcome</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${when(a.createdAt)}</td><td><span class="primary-text">${escapeHTML(a.actorId)}</span><span class="secondary-text">${escapeHTML(a.actorType)}</span></td><td>${escapeHTML(a.action)}</td><td>${escapeHTML(a.resourceType)} · ${escapeHTML(a.resourceId)}</td><td>${escapeHTML(intakeDetails(a)||"—")}</td><td>${badge(a.outcome)}</td></tr>`).join("")}</tbody></table></div>`:empty("No audit events","Events will appear when reports, configuration, approvals and actions occur.")}</section>`}
function jobTable(){const jobs=state.jobs.filter(j=>j.status!=="complete");const warning=state.dashboard.workerQueueStalled?`<div class="setup-warning"><strong>Worker queue stalled</strong><p>${escapeHTML(state.dashboard.workerHealthSummary||"Ready work is waiting without a fresh worker heartbeat.")}</p></div>`:"";if(!jobs.length)return warning+empty("Work queue is clear","No queued, running, retrying or dead jobs need attention.");return `${warning}<div class="table-wrap"><table class="data-table"><thead><tr><th>Work</th><th>Incident</th><th>Status</th><th>Attempts</th><th>Updated</th></tr></thead><tbody>${jobs.map(j=>{const status=j.status==="failed"?"retrying":j.status;const error=String(j.lastError||"").slice(0,300);return `<tr><td><span class="primary-text">${escapeHTML(j.type)}</span>${error?`<span class="secondary-text">${escapeHTML(error)}</span>`:""}</td><td>${escapeHTML(j.incidentId||"—")}</td><td>${badge(status)}</td><td>${j.attempts} / ${j.maxAttempts}</td><td>${when(j.updatedAt)}</td></tr>`}).join("")}</tbody></table></div>`}
function deliveryTable(){if(!state.deliveries.length)return empty("Delivery queue is clear","No queued, sending, retrying or dead WhatsApp messages need attention.");return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Channel</th><th>Status</th><th>Attempts</th><th>Safe failure category</th><th>Available</th><th>Created</th></tr></thead><tbody>${state.deliveries.map(d=>`<tr><td class="primary-text">${escapeHTML(d.channelType||"unknown")}</td><td>${badge(d.status==="failed"?"retrying":d.status)}</td><td>${d.attempts} / ${d.maxAttempts}</td><td>${escapeHTML(String(d.failureCategory||"—").replaceAll("_"," "))}</td><td>${when(d.availableAt)}</td><td>${when(d.createdAt)}</td></tr>`).join("")}</tbody></table></div>`}
function runtimeTable(){const rows=state.runtimeComponents.map(component=>`<tr><td class="primary-text">${escapeHTML(component.name)}</td><td>${badge(component.status)}</td><td>${escapeHTML(component.detail||"—")}</td><td>${when(component.updatedAt)}</td></tr>`).join("");return `<section class="card"><div class="card-head"><div><h2>Runtime components</h2><p>/healthz reports process liveness. /readyz additionally verifies MariaDB, migrations, and every required supervised loop.</p></div></div>${rows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Component</th><th>Status</th><th>Detail</th><th>Updated</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty("Runtime starting","Supervised components have not reported their state yet.")}</section>`}
function renderSystem(){const f=state.bootstrap.features;const ai=state.aiSettings;const provider=ai?.provider==="openai"?"OpenAI":"OpenAI-compatible fallback";const d=state.dashboard;const work=d.queuedJobs+d.runningJobs+d.retryingJobs+d.deadJobs;return `<div class="github-connection ${ai?.configured?"connected":"missing"}"><div><p class="eyebrow">AI CONNECTION</p><h2>${ai?.configured?`${provider} · ${escapeHTML(ai.model)}`:"OpenAI not configured"}</h2><p>${ai?.configured?`API key ${ai.source==="application"?`encrypted in Echo · updated ${when(ai.updatedAt)}`:"provided by the environment"}.`:"Add the OpenAI key Echo should use for repository-backed diagnosis and patch planning."}</p></div><div class="setup-actions"><button class="button ${ai?.configured?"secondary":"primary"}" id="configure-ai">${ai?.source==="application"?"Replace key":"Configure OpenAI"}</button>${ai?.source==="application"?`<button class="button danger" id="remove-ai">Remove</button>`:""}</div></div><div class="metric-grid">${metric("WhatsApp",state.whatsapp.status,`${d.pendingWhatsAppMessages} pending · ${d.deadWhatsAppMessages} dead`,d.deadWhatsAppMessages?"--coral":"--mint")}${metric("Runtime loops",state.runtimeReady?"ready":"degraded",`${state.runtimeComponents.filter(c=>c.status==="running").length} / ${state.runtimeComponents.length} running`,state.runtimeReady?"--mint":"--coral")}${metric("AI analysis",f.ai?"enabled":"disabled",ai?.model||"Advisory only","--blue")}${metric("GitHub",f.github?"connected":"missing",f.github?`Token for ${state.githubSettings?.account||"account"}`:"Configure in Repositories","--amber")}${metric("Worker",f.worker?"enabled":"disabled",`${work} visible · ${d.deadJobs} dead${d.workerQueueStalled?" · STALLED":""}`,(d.deadJobs||d.workerQueueStalled)?"--coral":"--mint")}</div>${runtimeTable()}<section class="card"><div class="card-head"><div><h2>WhatsApp delivery queue</h2><p>Read-only attempts and safe failure categories. Message bodies and destinations are omitted; dead messages are never retried blindly.</p></div></div>${deliveryTable()}</section><section class="card"><div class="card-head"><div><h2>Job queue</h2><p>Durable worker leases and recent failure evidence. This view is read-only; dead work is never retried blindly.</p></div></div>${jobTable()}</section><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Trust boundaries</h2><p>Credentials are deliberately separated</p></div></div><div class="card-body feature-grid"><div class="feature"><strong>Gateway</strong><p>WhatsApp session only. No repository credentials.</p></div><div class="feature"><strong>Control plane</strong><p>Policy, approvals, encrypted settings and audit.</p></div><div class="feature"><strong>Workers</strong><p>Disposable repository workspaces with bounded evidence.</p></div><div class="feature"><strong>Deployments</strong><p>CI adapters receive immutable artifact references.</p></div></div></section><section class="card"><div class="card-head"><div><h2>Environment</h2><p>Current runtime posture</p></div></div><div class="card-body"><p class="report">${escapeHTML(state.bootstrap.environment)}\nPublic UI session: authenticated\nCSRF protection: enabled\nEncrypted settings: enabled\nContent security policy: enabled\nAudit logging: enabled</p></div></section></div>`}

