document.addEventListener("submit",async e=>{const form=e.target;if(form.id!=="runbook-form")return;e.preventDefault();e.stopImmediatePropagation();const obj=Object.fromEntries(new FormData(form).entries());const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;try{await api("/api/v1/service-runbooks",{method:"POST",body:JSON.stringify(obj)});$("#modal").close();await refreshAll();toast(obj.id?"Service runbook updated":"Service runbook added");await openService(obj.serviceId)}catch(err){if(submit)submit.disabled=false;toast(err.message)}});

document.addEventListener("submit",async e=>{e.preventDefault();const form=e.target;if(form.id==="login-form"){try{await api("/api/v1/auth/login",{method:"POST",body:JSON.stringify({token:form.elements.namedItem("token").value})});$("#login-error").textContent="";await boot()}catch(err){$("#login-error").textContent=err.message};return}const fd=new FormData(form);const obj=Object.fromEntries(fd.entries());const checked=name=>Boolean(form.elements.namedItem(name)?.checked);const inSetup=state.view==="setup";try{if(form.id==="service-form"){obj.enabled=checked("enabled");obj.heartbeatTimeoutSeconds=Number(obj.heartbeatTimeoutSeconds||0);obj.metadata=JSON.parse(obj.metadata);await api("/api/v1/services",{method:"POST",body:JSON.stringify(obj)})}if(form.id==="dependency-form"){await api("/api/v1/service-dependencies",{method:"POST",body:JSON.stringify(obj)});$("#modal").close();await refreshAll();toast("Service dependency added");await openService(obj.serviceId);return}if(form.id==="maintenance-form"){obj.startsAt=new Date(obj.startsAt).toISOString();obj.endsAt=new Date(obj.endsAt).toISOString();await api("/api/v1/maintenance",{method:"POST",body:JSON.stringify(obj)});$("#modal").close();await refreshAll();render();toast("Maintenance scheduled; evidence collection remains active");return}if(form.id==="github-token-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;state.githubSettings=await api("/api/v1/settings/github",{method:"PUT",body:JSON.stringify({token:obj.token})});state.bootstrap.features.github=true;form.elements.namedItem("token").value="";$("#modal").close();toast(`GitHub connected as ${state.githubSettings.account}`);await refreshAll();render();return}if(form.id==="ai-settings-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;state.aiSettings=await api("/api/v1/settings/ai",{method:"PUT",body:JSON.stringify({apiKey:obj.apiKey,model:obj.model})});state.bootstrap.features.ai=true;form.elements.namedItem("apiKey").value="";$("#modal").close();toast(`OpenAI connected with ${state.aiSettings.model}`);await refreshAll();render();return}if(form.id==="owner-form"){state.ownerSettings=await api("/api/v1/settings/owner",{method:"PUT",body:JSON.stringify({contactId:obj.contactId})});state.bootstrap.features.owner=true;$("#modal").close();toast(`${state.ownerSettings.displayName||state.ownerSettings.jid} is now the owner`);await refreshAll();render();return}if(form.id==="briefing-form"){state.briefingSettings=await api("/api/v1/settings/briefing",{method:"PUT",body:JSON.stringify({enabled:checked("enabled"),localTime:obj.localTime,timezone:obj.timezone})});$("#modal").close();toast(state.briefingSettings.enabled?`Daily brief scheduled for ${state.briefingSettings.localTime} ${state.briefingSettings.timezone}`:"Daily brief disabled");await refreshAll();render();return}if(form.id==="project-form"){obj.enabled=checked("enabled");const saved=await api("/api/v1/projects",{method:"POST",body:JSON.stringify(obj)});state.setupProjectId=saved.id;if(inSetup)state.setupStep=2}if(form.id==="group-form"){obj.mentionRequired=checked("mentionRequired");obj.enabled=checked("enabled");await api("/api/v1/groups",{method:"POST",body:JSON.stringify(obj)});state.setupProjectId=obj.projectId;if(inSetup)state.setupStep=4}if(form.id==="github-discovery-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;const repository=state.githubDiscovery?.repositories?.find(r=>r.fullName===obj.fullName);if(!repository)throw new Error("The discovered repository is no longer available");const saved=await api("/api/v1/repositories",{method:"POST",body:JSON.stringify({projectId:obj.projectId,owner:repository.owner,name:repository.name,role:obj.role,defaultBranch:repository.defaultBranch,readOnly:true,enabled:true})});state.setupProjectId=saved.projectId;state.githubDiscovery=null;$("#modal").close();await refreshAll();render();toast(`${repository.fullName} linked read-only`);return}if(form.id==="repo-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;obj.readOnly=checked("readOnly");obj.enabled=checked("enabled");const saved=await api("/api/v1/repositories",{method:"POST",body:JSON.stringify(obj)});state.setupProjectId=saved.projectId;$("#modal").close();await refreshAll();render();toast(saved.readOnly?"Repository remains read-only":"Approved changes enabled; reopen the incident to request patch approval");return}if(form.id==="environment-form"){obj.requiresApproval=checked("requiresApproval");obj.protected=checked("protected");obj.config=JSON.parse(obj.config);await api("/api/v1/environments",{method:"POST",body:JSON.stringify(obj)})}if(form.id==="patch-approval-form"){const repo=state.repos.find(r=>r.id===obj.repositoryId);if(!repo)throw new Error("Repository is no longer available");const result=await api(`/api/v1/incidents/${form.dataset.incidentId}/approvals`,{method:"POST",body:JSON.stringify({actionType:"prepare_patch",action:{repositoryId:repo.id,repository:`${repo.owner}/${repo.name}`}})});toast(`Approval created · code ${result.displayNonce}`);$("#modal").close();await refreshAll();navigate("approvals");return}$("#modal").close();toast("Configuration saved");await refreshAll();render()}catch(err){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=false;toast(err.message)}});

